var panel, abierto = false;

function start() {

	panel = document.createElement( 'div' );
	panel.style.cssText = `
		position: fixed; top: 20px; right: 20px; width: 260px;
		background: rgba(20,20,20,0.92); color: #fff;
		font-family: Arial, sans-serif; padding: 16px 18px;
		border-radius: 12px; box-shadow: 0 6px 24px rgba(0,0,0,0.4);
		display: none; z-index: 1500; font-size: 14px;
	`;
	panel.innerHTML = `
		<div style="display:flex; justify-content:space-between; align-items:center;">
			<h3 style="margin:0; font-size:18px;">🍔 Ingredientes</h3>
			<span id="cerrarPanel" style="cursor:pointer; font-size:22px; padding:4px;">✕</span>
		</div>
		<ul style="padding-left:18px; margin:12px 0 0; line-height:1.7;">
			<li>Pan brioche con ajonjolí</li>
			<li>Carne de res 100%</li>
			<li>Queso cheddar</li>
			<li>Tocineta crocante</li>
			<li>Salsa especial</li>
		</ul>
	`;
	document.body.appendChild( panel );

	// Evita que tocar el panel llegue al raycast de MindARController
	panel.addEventListener( 'pointerdown', function ( e ) { e.stopPropagation(); } );
	panel.querySelector( '#cerrarPanel' ).addEventListener( 'click', function () { mostrar( false ); } );

	// MindARController llama a esto cuando tocan la hamburguesa
	this.onClick = function () { mostrar( ! abierto ); };

}

function stop() {
	if ( panel && panel.parentNode ) panel.parentNode.removeChild( panel );
}

function mostrar( valor ) {
	abierto = valor;
	panel.style.display = valor ? 'block' : 'none';
}

function visibleEnEscena( obj ) {
	while ( obj ) {
		if ( obj.visible === false ) return false;
		obj = obj.parent;
	}
	return true;
}

function update( event ) {

	// Si se pierde el marcador, cierra el panel
	if ( abierto && ! visibleEnEscena( this ) ) mostrar( false );

	// Giro lento y constante (pausado con el panel abierto)
	if ( ! abierto ) this.rotation.y += 0.5 * event.delta / 1000;

}
